package com.progressly.activity.domain;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="tasks") public class Task { public enum Status{PENDING,IN_PROGRESS,COMPLETED,SKIPPED,CANCELLED} public enum Recurrence{NONE,DAILY,WEEKLY,MONTHLY,CUSTOM} @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID userId; @Column(nullable=false,length=180) String title; @Column(length=2000) String description; String category,priority; LocalDate dueDate; LocalTime dueTime; Integer estimatedMinutes,actualMinutes; UUID goalId,milestoneId; @Enumerated(EnumType.STRING) @Column(nullable=false) Status status; @Enumerated(EnumType.STRING) @Column(nullable=false) Recurrence recurrence; @Column(nullable=false,updatable=false) Instant createdAt; Instant updatedAt; protected Task(){} public Task(UUID u,String t,String d,String c,String p,LocalDate date,LocalTime time,Integer estimate,UUID goal,UUID milestone,Recurrence recurrence){userId=u;title=t;description=d;category=c;priority=p;dueDate=date;dueTime=time;estimatedMinutes=estimate;goalId=goal;milestoneId=milestone;status=Status.PENDING;this.recurrence=recurrence==null?Recurrence.NONE:recurrence;} @PrePersist void c(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void u(){updatedAt=Instant.now();} public UUID getId(){return id;} public UUID getUserId(){return userId;} public String getTitle(){return title;} public String getDescription(){return description;} public String getCategory(){return category;} public String getPriority(){return priority;} public LocalDate getDueDate(){return dueDate;} public LocalTime getDueTime(){return dueTime;} public Integer getEstimatedMinutes(){return estimatedMinutes;} public Integer getActualMinutes(){return actualMinutes;} public UUID getGoalId(){return goalId;} public UUID getMilestoneId(){return milestoneId;} public Status getStatus(){return status;} public Recurrence getRecurrence(){return recurrence;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void update(String t,String d,String c,String p,LocalDate date,LocalTime time,Integer estimate,Integer actual,UUID goal,UUID milestone,Recurrence recurrence,Status status){title=t;description=d;category=c;priority=p;dueDate=date;dueTime=time;estimatedMinutes=estimate;actualMinutes=actual;goalId=goal;milestoneId=milestone;this.recurrence=recurrence;this.status=status;} public void status(Status s){status=s;} }
